"""Python half of the capability parity test (go/internal/capabilities/python_test.go).

Runs the REAL Python VaultManager.execute_capability on a copy of a G0
fixture vault for each case in CASES_JSON and prints, as JSON on stdout, one
entry per case: the exception class name ("" on success) and the audit rows
(action, details) the call appended.

Usage: python pyexec.py VAULT_DIR MASTER_FILE KEY_HEX CASES_JSON

All key material is throwaway test data generated by the Go test.
"""

import json
import os
import sys

from rgt_vault.hook import OffHook
from rgt_vault.providers.base import MasterSecretProvider
from rgt_vault.token import HMACTokenVerifier
from rgt_vault.vault import VaultManager


class FileMaster(MasterSecretProvider):
    def __init__(self, path):
        self.path = path

    def get_secret(self):
        with open(self.path, "rb") as f:
            return f.read()


def main():
    vault_dir, master, key_hex, cases_path = sys.argv[1:5]
    key = bytes.fromhex(key_hex)
    with open(cases_path) as f:
        cases = json.load(f)
    with open(os.path.join(vault_dir, "policy.yaml")) as f:
        policy = f.read()
    verifier = HMACTokenVerifier(key)
    other = HMACTokenVerifier(bytes(reversed(key)))
    hook = OffHook()
    vm = VaultManager(
        db_path=os.path.join(vault_dir, "vault.db"),
        master_provider=FileMaster(master),
        policy_yaml=policy,
        hook=hook,
        token_verifier=verifier,
    )
    out = []
    for c in cases:
        t = c["token"]
        if t["kind"] == "ok":
            token = verifier.sign(t["agent"], t["capability"], t["version"], t.get("bindings") or {}, 60)
        elif t["kind"] == "badsig":
            token = other.sign(t["agent"], t["capability"], t["version"], t.get("bindings") or {}, 60)
        else:
            token = t["raw"]
        vm.token_verifier = None if c.get("no_verifier") else verifier
        if c.get("frozen"):
            hook.freeze("test")
        n_before = len(vm.storage.iter_audit_log())
        err = ""
        try:
            vm.execute_capability(
                capability_name=c["capability"],
                payload=c["payload"],
                agent_id=c["agent"],
                capability_token=token,
                capability_version=c["version"],
            )
        except Exception as e:  # report the class, compare in Go
            err = type(e).__name__
        hook.unfreeze("test")
        new = vm.storage.iter_audit_log()[n_before:]
        out.append({"error": err, "rows": [[r["action"], r["details"]] for r in new]})
    json.dump(out, sys.stdout)


if __name__ == "__main__":
    main()
